import axios from 'axios';
import constants from 'config/constants';

// Notifications a user has received (the same list the mobile app's Notifications screen shows). Plain async calls, no
// reducer: only the Notifications page and the dashboard card use them.
//
// The backend builds one page from three recipient tables (guardians, employees, admins) and gives each its own page of
// `size`, so a page can hold up to three times `size`, in no particular order - hence the sort here.
const BASE = constants.API_BASE_URL;

export const sortNewestFirst = list =>
  [...list].sort((a, b) => new Date(b.creationDateTime || 0) - new Date(a.creationDateTime || 0));

export const fetchReceivedNotificationsApi = async ({ userId, page = 1, size = 10, token }) => {
  const res = await axios.get(
    `${BASE}/api/received-notification/${userId}${constants.makeParams({ pageNo: page, pageSize: size })}`,
    constants.setHeader(token)
  );
  return sortNewestFirst(res.data || []);
};

export const fetchUnreadNotificationCountApi = async ({ userId, token }) => {
  const res = await axios.get(`${BASE}/api/unread-notification-count/${userId}`, constants.setHeader(token));
  return res.data?.unreadCount || 0;
};

export const markNotificationReadApi = ({ notificationId, token }) =>
  axios.post(`${BASE}/api/notification-mark-as-read/${notificationId}`, null, constants.setHeader(token));
