import React, { useCallback, useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Paper, Tabs, Tab } from '@material-ui/core';
import Avatar from '@material-ui/core/Avatar';
import NotificationsActiveIcon from '@material-ui/icons/NotificationsActive';
import Dialog from '@material-ui/core/Dialog';
import DialogTitle from '@material-ui/core/DialogTitle';
import DialogContent from '@material-ui/core/DialogContent';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { showToast } from 'actions/admin/auth';
import {
  fetchReceivedNotificationsApi,
  fetchUnreadNotificationCountApi,
  markNotificationReadApi,
} from 'actions/admin/notifications';
import { formResMessage } from 'utils/commonFunc';
import { CommonLoader } from 'views/admin/Common/Loader';
import RichText from 'views/admin/Common/RichText';
import NotificationItem, { notificationCss } from './NotificationItem';
import EmptyState from 'views/admin/Common/EmptyState';

// Same size as the mobile app: the backend reads three tables and gives each its own page of this size.
const PAGE_SIZE = 10;
// Most extra pages "Mark all as read" loads to reach older unread notifications.
const MARK_ALL_MAX_PAGES = 30;

// Notifications the logged-in user has received, newest first, laid out like the mobile app's Notifications screen.
// The API can mark one notification read and cannot mark unread, so there is no "mark as unread" here.
const NotificationsPage = () => {
  const dispatch = useDispatch();
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);

  const [list, setList] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [isMarkingAll, setIsMarkingAll] = useState(false);
  const [openItem, setOpenItem] = useState(null);
  const [filter, setFilter] = useState(0); // 0 = all, 1 = unread only

  const showWarning = useCallback((message, type) => dispatch(showToast(message, type)), [dispatch]);

  const refreshCount = useCallback(async () => {
    try {
      const count = await fetchUnreadNotificationCountApi({ userId: loggedUserId, token: loggedUserToken });
      setUnreadCount(count);
      return count;
    } catch (err) {
      return null;
    }
  }, [loggedUserId, loggedUserToken]);

  // Page 1 replaces the list, later pages are added to it. Resolves to the page that came back.
  const loadPage = useCallback(
    async (pageNumber, current) => {
      const fresh = await fetchReceivedNotificationsApi({
        userId: loggedUserId,
        page: pageNumber,
        size: PAGE_SIZE,
        token: loggedUserToken,
      });
      const known = new Set(current.map(item => item.notificationId));
      const added = fresh.filter(item => !known.has(item.notificationId));
      // A page with nothing new is the last one (also stops a backend that ignores the page number).
      setHasMore(added.length > 0);
      setPage(pageNumber);
      const merged = [...current, ...added];
      setList(merged);
      return merged;
    },
    [loggedUserId, loggedUserToken]
  );

  useEffect(() => {
    if (!loggedUserId) return;
    setIsLoading(true);
    Promise.all([loadPage(1, []), refreshCount()])
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setIsLoading(false));
  }, [loggedUserId, loadPage, refreshCount, showWarning]);

  const loadMore = async () => {
    setIsLoadingMore(true);
    try {
      await loadPage(page + 1, list);
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setIsLoadingMore(false);
  };

  const markRead = async items => {
    const unread = items.filter(item => item.readStatus === 'UNREAD');
    await Promise.all(
      unread.map(item =>
        markNotificationReadApi({ notificationId: item.notificationId, token: loggedUserToken }).catch(() => null)
      )
    );
    const ids = new Set(unread.map(item => item.notificationId));
    setList(prev => prev.map(item => (ids.has(item.notificationId) ? { ...item, readStatus: 'READ' } : item)));
    return refreshCount();
  };

  const openNotification = item => {
    setOpenItem(item);
    markRead([item]);
  };

  // The API has no "read all": this marks what is loaded and keeps paging through older ones while the server still
  // reports unread (bounded, so a huge backlog cannot loop forever).
  const markAllRead = async () => {
    if (isMarkingAll) return;
    setIsMarkingAll(true);
    try {
      let current = list;
      let count = await markRead(current);
      let pages = 0;
      let more = hasMore;
      let pageNumber = page;
      while (count > 0 && more && pages < MARK_ALL_MAX_PAGES) {
        pages += 1;
        pageNumber += 1;
        const before = current.length;
        current = await loadPage(pageNumber, current);
        more = current.length > before;
        count = await markRead(current);
      }
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setIsMarkingAll(false);
  };

  const shown = filter === 1 ? list.filter(item => item.readStatus === 'UNREAD') : list;
  // "Today", "Yesterday", then the date: the list is newest first, so a heading goes in where the day changes.
  const dayLabel = value => {
    const day = moment(value);
    if (day.isSame(moment(), 'day')) return 'Today';
    if (day.isSame(moment().subtract(1, 'day'), 'day')) return 'Yesterday';
    return day.format('dddd, DD MMM YYYY');
  };

  return (
    <div className="content">
      <style>{notificationCss}</style>
      <Paper square>
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            alignItems: 'center',
            gap: 12,
            padding: '14px 16px',
            borderBottom: '1px solid #eee',
          }}>
          <Avatar style={{ backgroundColor: `${colors.accent}1a`, color: colors.accent, width: 36, height: 36 }}>
            <NotificationsActiveIcon style={{ fontSize: 20 }} />
          </Avatar>
          <div style={{ flex: '1 1 200px', minWidth: 0 }}>
            <div style={{ fontWeight: 'bold', fontSize: 18, color: '#2b2b2b' }}>Notifications</div>
            <div style={{ fontSize: 12, color: '#7d7d7d' }}>
              {unreadCount > 0 ? `${unreadCount} unread` : 'You are all caught up'}
            </div>
          </div>
          {unreadCount > 0 && (
            <CustomButton
              size="small"
              variant="outlined"
              name={isMarkingAll ? 'Marking...' : 'Mark all as read'}
              disabled={isMarkingAll}
              onClick={markAllRead}
            />
          )}
        </div>
        <Tabs
          value={filter}
          onChange={(e, value) => setFilter(value)}
          indicatorColor=""
          textColor="inherit"
          variant="scrollable"
          scrollButtons="off">
          {['All', `Unread${unreadCount > 0 ? ` (${unreadCount})` : ''}`].map((label, index) => (
            <Tab
              key={label}
              label={label}
              style={{
                fontWeight: 'bold',
                minWidth: 110,
                color: filter === index ? colors.accent : '',
                borderBottom: filter === index ? `3px solid ${colors.accent}` : '3px solid transparent',
              }}
            />
          ))}
        </Tabs>
        {isLoading ? (
          <div style={{ padding: 30, textAlign: 'center' }}>
            <CommonLoader />
          </div>
        ) : shown.length ? (
          <>
            {shown.map((item, index) => (
              <React.Fragment key={item.notificationId}>
                {(index === 0 || !moment(item.creationDateTime).isSame(shown[index - 1].creationDateTime, 'day')) && (
                  <div
                    style={{
                      padding: '6px 16px',
                      fontSize: 11,
                      fontWeight: 'bold',
                      letterSpacing: '0.06em',
                      textTransform: 'uppercase',
                      color: colors.grey2,
                      background: '#FAF5FD',
                      borderBottom: '1px solid #f0e6f6',
                    }}>
                    {dayLabel(item.creationDateTime)}
                  </div>
                )}
                <NotificationItem
                  item={item}
                  unread={item.readStatus === 'UNREAD'}
                  onClick={() => openNotification(item)}
                />
              </React.Fragment>
            ))}
            <div style={{ textAlign: 'center', padding: 14 }}>
              {hasMore ? (
                <CustomButton
                  size="small"
                  variant="outlined"
                  name={isLoadingMore ? 'Loading...' : 'Load more'}
                  disabled={isLoadingMore}
                  onClick={loadMore}
                />
              ) : (
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <div style={{ flex: 1, height: 1, background: '#e3e3e3' }} />
                  <span
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: 6,
                      fontSize: 12,
                      fontWeight: 'bold',
                      color: colors.accent,
                      background: `${colors.accent}12`,
                      borderRadius: 14,
                      padding: '4px 12px',
                    }}>
                    <i className="fas fa-check-circle" /> No more notifications
                  </span>
                  <div style={{ flex: 1, height: 1, background: '#e3e3e3' }} />
                </div>
              )}
            </div>
          </>
        ) : (
          <EmptyState
            title={filter === 1 ? 'No unread notifications' : 'No notifications yet'}
            subtitle={
              filter === 1
                ? 'Everything you have received is read.'
                : 'Messages sent to you from the school show up here.'
            }
            style={{ margin: 16 }}
          />
        )}
      </Paper>
      <Dialog open={!!openItem} onClose={() => setOpenItem(null)} fullWidth maxWidth="sm">
        <DialogTitle>{openItem?.title || 'Notification'}</DialogTitle>
        <DialogContent style={{ paddingBottom: 20 }}>
          <div style={{ fontSize: 11, color: '#9a9a9a', marginBottom: 10 }}>
            {openItem?.creationDateTime ? moment(openItem.creationDateTime).format('MMM DD, YYYY hh:mm A') : ''}
          </div>
          <RichText text={openItem?.textBody || ''} embed />
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default NotificationsPage;
